    "+ Elektrodenmaterial": "+ \u03A5\u03BB\u03B9\u03BA\u03CC \u03B7\u03BB\u03B5\u03BA\u03C4\u03C1\u03BF\u03B4\u03AF\u03BF\u03C5",
