    "Bindungsart w\xE4hlen": "\u0AAC\u0A82\u0AA7\u0AA8\u0AA8\u0ACB \u0AAA\u0ACD\u0AB0\u0A95\u0ABE\u0AB0 \u0AAA\u0AB8\u0A82\u0AA6 \u0A95\u0AB0\u0ACB",
