    "Kategorie: Nichtmetalle": "\u0AB6\u0ACD\u0AB0\u0AC7\u0AA3\u0AC0: \u0A85\u0AA7\u0ABE\u0AA4\u0AC1",
    Nichtmetalle: "\u0A85\u0AA7\u0ABE\u0AA4\u0AC1",
    "Kategorie: Edelgase": "\u0AB6\u0ACD\u0AB0\u0AC7\u0AA3\u0AC0: \u0AA8\u0ABF\u0AB7\u0ACD\u0A95\u0ACD\u0AB0\u0ABF\u0AAF \u0AB5\u0ABE\u0AAF\u0AC1",
    Edelgase: "\u0AA8\u0ABF\u0AB7\u0ACD\u0A95\u0ACD\u0AB0\u0ABF\u0AAF \u0AB5\u0ABE\u0AAF\u0AC1",
    "Kategorie: Alkalimetalle": "\u0AB6\u0ACD\u0AB0\u0AC7\u0AA3\u0AC0: \u0A95\u0ACD\u0AB7\u0ABE\u0AB0\u0AC0\u0AAF \u0AA7\u0ABE\u0AA4\u0AC1",
