    \u00DCbergangsmetalle: "\u0AB8\u0A82\u0A95\u0ACD\u0AB0\u0AAE\u0AA3 \u0AA7\u0ABE\u0AA4\u0AC1",
    "Kategorie: Lanthanoide": "\u0AB6\u0ACD\u0AB0\u0AC7\u0AA3\u0AC0: \u0AB2\u0AC7\u0AA8\u0ACD\u0AA5\u0AC7\u0AA8\u0ABE\u0A87\u0AA1",
    Lanthanoide: "\u0AB2\u0AC7\u0AA8\u0ACD\u0AA5\u0AC7\u0AA8\u0ABE\u0A87\u0AA1",
    "Kategorie: Actinoide": "\u0AB6\u0ACD\u0AB0\u0AC7\u0AA3\u0AC0: \u0A8F\u0A95\u0ACD\u0A9F\u0ABF\u0AA8\u0ABE\u0A87\u0AA1",
