    "Kategorie: Unbekannt": "\u0AB6\u0ACD\u0AB0\u0AC7\u0AA3\u0AC0: \u0A85\u0A9C\u0ACD\u0A9E\u0ABE\u0AA4",
    Unbekannt: "\u0A85\u0A9C\u0ACD\u0A9E\u0ABE\u0AA4",
    "Suche nach Name oder Symbol": "\u0AA8\u0ABE\u0AAE \u0A85\u0AA5\u0AB5\u0ABE \u0AAA\u0ACD\u0AB0\u0AA4\u0AC0\u0A95\u0AA5\u0AC0 \u0AB6\u0ACB\u0AA7\u0ACB",
    Verbindungen: "\u0AB8\u0A82\u0AAF\u0ACB\u0A9C\u0AA8\u0ACB",
