    Laborger\u00E4te: "\u0CAA\u0CCD\u0CB0\u0CAF\u0CCB\u0C97\u0CBE\u0CB2\u0CAF \u0C89\u0CAA\u0C95\u0CB0\u0CA3\u0C97\u0CB3\u0CC1",
    Elektronik: "\u0C8E\u0CB2\u0CC6\u0C95\u0CCD\u0C9F\u0CCD\u0CB0\u0CBE\u0CA8\u0CBF\u0C95\u0CCD\u0CB8\u0CCD",
