    "Filter zur\xFCcksetzen": "\u0B2B\u0B3F\u0B32\u0B4D\u0B1F\u0B30\u0B4D \u0B2A\u0B41\u0B28\u0B03\u0B38\u0B47\u0B1F\u0B4D",
    "Kategorie: Halogene": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B39\u0B3E\u0B32\u0B4B\u0B1C\u0B47\u0B28\u0B4D",
    Halogene: "\u0B39\u0B3E\u0B32\u0B4B\u0B1C\u0B47\u0B28\u0B4D",
    "Kategorie: Nichtmetalle": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B05\u0B27\u0B3E\u0B24\u0B41",
    Nichtmetalle: "\u0B05\u0B27\u0B3E\u0B24\u0B41",
    "Kategorie: Edelgase": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B09\u0B24\u0B4D\u0B15\u0B43\u0B37\u0B4D\u0B1F \u0B17\u0B4D\u0B5F\u0B3E\u0B38\u0B4D",
    Edelgase: "\u0B09\u0B24\u0B4D\u0B15\u0B43\u0B37\u0B4D\u0B1F \u0B17\u0B4D\u0B5F\u0B3E\u0B38\u0B4D",
    "Kategorie: Alkalimetalle": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B15\u0B4D\u0B37\u0B3E\u0B30 \u0B27\u0B3E\u0B24\u0B41",
    Alkalimetalle: "\u0B15\u0B4D\u0B37\u0B3E\u0B30 \u0B27\u0B3E\u0B24\u0B41",
    "Kategorie: Erdalkalimetalle": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B15\u0B4D\u0B37\u0B3E\u0B30\u0B40\u0B5F \u0B2E\u0B43\u0B24\u0B4D\u0B24\u0B3F\u0B15\u0B3E \u0B27\u0B3E\u0B24\u0B41",
    Erdalkalimetalle: "\u0B15\u0B4D\u0B37\u0B3E\u0B30\u0B40\u0B5F \u0B2E\u0B43\u0B24\u0B4D\u0B24\u0B3F\u0B15\u0B3E \u0B27\u0B3E\u0B24\u0B41",
    "Kategorie: Halbmetalle": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B09\u0B2A\u0B27\u0B3E\u0B24\u0B41",
    Halbmetalle: "\u0B09\u0B2A\u0B27\u0B3E\u0B24\u0B41",
    "Kategorie: \xDCbergangsmetalle": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B38\u0B02\u0B15\u0B4D\u0B30\u0B2E\u0B23 \u0B27\u0B3E\u0B24\u0B41",
    \u00DCbergangsmetalle: "\u0B38\u0B02\u0B15\u0B4D\u0B30\u0B2E\u0B23 \u0B27\u0B3E\u0B24\u0B41",
    "Kategorie: Lanthanoide": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B32\u0B3E\u0B28\u0B4D\u0B25\u0B3E\u0B28\u0B3E\u0B07\u0B21\u0B4D",
    Lanthanoide: "\u0B32\u0B3E\u0B28\u0B4D\u0B25\u0B3E\u0B28\u0B3E\u0B07\u0B21\u0B4D",
    "Kategorie: Actinoide": "\u0B36\u0B4D\u0B30\u0B47\u0B23\u0B40: \u0B06\u0B15\u0B4D\u0B1F\u0B3F\u0B28\u0B3E\u0B07\u0B21\u0B4D",
