    "Lehrkraft Steuerung": "\u0D9C\u0DD4\u0DBB\u0DD4 \u0DB4\u0DCF\u0DBD\u0DB1",
    Allgemein: "\u0DC3\u0DCF\u0DB8\u0DCF\u0DB1\u0DCA\u200D\u0DBA",
    Ausblenden: "\u0DC3\u0D9F\u0DC0\u0DB1\u0DCA\u0DB1",
    Molek\u00FCle: "\u0D85\u0DAB\u0DD4",
