    Elektronik: "\u0D89\u0DBD\u0DD9\u0D9A\u0DCA\u0DA7\u0DCA\u200D\u0DBB\u0DDC\u0DB1\u0DD2\u0D9A \u0D8B\u0DB4\u0D9A\u0DBB\u0DAB",
    "Panel anzeigen": "\u0DB4\u0DD4\u0DC0\u0DBB\u0DD4\u0DC0 \u0DB4\u0DD9\u0DB1\u0DCA\u0DC0\u0DB1\u0DCA\u0DB1",
    Objekt: "\u0DC0\u0DC3\u0DCA\u0DAD\u0DD4\u0DC0",
