    Verbindungen: "\u0DC3\u0D82\u0DBA\u0DDD\u0D9C",
    "neu anlegen": "\u0D85\u0DBD\u0DD4\u0DAD\u0DD2\u0DB1\u0DCA \u0DC3\u0DCF\u0DAF\u0DB1\u0DCA\u0DB1",
    Gegenst\u00FCck: "\u0DB4\u0DCA\u200D\u0DBB\u0DAD\u0DD2\u0DC0\u0DD2\u0DBB\u0DD4\u0DAF\u0DCA\u0DB0\u0DBA",
