    Tenness: "\u0DA7\u0DD9\u0DB1\u0DD9\u0DC3\u0DD3\u0DB1\u0DCA",
    Oganesson: "\u0D94\u0D9C\u0DB1\u0DD9\u0DC3\u0DB1\u0DCA",
