    "Lehrkraft Steuerung": "\u0D05\u0D27\u0D4D\u0D2F\u0D3E\u0D2A\u0D15 \u0D28\u0D3F\u0D2F\u0D28\u0D4D\u0D24\u0D4D\u0D30\u0D23\u0D19\u0D4D\u0D19\u0D7E",
    Allgemein: "\u0D2A\u0D4A\u0D24\u0D41\u0D35\u0D3E\u0D2F\u0D24\u0D4D",
    Ausblenden: "\u0D2E\u0D31\u0D2F\u0D4D\u0D15\u0D4D\u0D15\u0D41\u0D15",
    Molek\u00FCle: "\u0D24\u0D28\u0D4D\u0D2E\u0D3E\u0D24\u0D4D\u0D30\u0D15\u0D7E",
