    Elektronik: "\u0D07\u0D32\u0D15\u0D4D\u0D1F\u0D4D\u0D30\u0D4B\u0D23\u0D3F\u0D15\u0D4D\u0D38\u0D4D",
    "Panel anzeigen": "\u0D2A\u0D3E\u0D28\u0D7D \u0D15\u0D3E\u0D23\u0D3F\u0D15\u0D4D\u0D15\u0D41\u0D15",
    Objekt: "\u0D12\u0D2C\u0D4D\u0D1C\u0D15\u0D4D\u0D31\u0D4D\u0D31\u0D4D",
    "Objekt leeren": "\u0D12\u0D2C\u0D4D\u0D1C\u0D15\u0D4D\u0D31\u0D4D\u0D31\u0D4D \u0D36\u0D42\u0D28\u0D4D\u0D2F\u0D2E\u0D3E\u0D15\u0D4D\u0D15\u0D41\u0D15",
