    zur\u00FCcksetzen: "\u0D2A\u0D41\u0D28\u0D03\u0D38\u0D1C\u0D4D\u0D1C\u0D2E\u0D3E\u0D15\u0D4D\u0D15\u0D41\u0D15",
    hinzuf\u00FCgen: "\u0D1A\u0D47\u0D7C\u0D15\u0D4D\u0D15\u0D41\u0D15",
