    "Kategorie: Halogene": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E2E\u0E32\u0E42\u0E25\u0E40\u0E08\u0E19",
    Halogene: "\u0E2E\u0E32\u0E42\u0E25\u0E40\u0E08\u0E19",
    "Kategorie: Nichtmetalle": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E2D\u0E42\u0E25\u0E2B\u0E30",
    Nichtmetalle: "\u0E2D\u0E42\u0E25\u0E2B\u0E30",
    "Kategorie: Edelgase": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E01\u0E4A\u0E32\u0E0B\u0E21\u0E35\u0E15\u0E23\u0E30\u0E01\u0E39\u0E25",
    Edelgase: "\u0E01\u0E4A\u0E32\u0E0B\u0E21\u0E35\u0E15\u0E23\u0E30\u0E01\u0E39\u0E25",
    "Kategorie: Alkalimetalle": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E42\u0E25\u0E2B\u0E30\u0E41\u0E2D\u0E25\u0E04\u0E32\u0E44\u0E25",
    Alkalimetalle: "\u0E42\u0E25\u0E2B\u0E30\u0E41\u0E2D\u0E25\u0E04\u0E32\u0E44\u0E25",
    "Kategorie: Erdalkalimetalle": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E42\u0E25\u0E2B\u0E30\u0E41\u0E2D\u0E25\u0E04\u0E32\u0E44\u0E25\u0E19\u0E4C\u0E40\u0E2D\u0E34\u0E23\u0E4C\u0E17",
    Erdalkalimetalle: "\u0E42\u0E25\u0E2B\u0E30\u0E41\u0E2D\u0E25\u0E04\u0E32\u0E44\u0E25\u0E19\u0E4C\u0E40\u0E2D\u0E34\u0E23\u0E4C\u0E17",
    "Kategorie: Halbmetalle": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E01\u0E36\u0E48\u0E07\u0E42\u0E25\u0E2B\u0E30",
    Halbmetalle: "\u0E01\u0E36\u0E48\u0E07\u0E42\u0E25\u0E2B\u0E30",
    "Kategorie: \xDCbergangsmetalle": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E42\u0E25\u0E2B\u0E30\u0E17\u0E23\u0E32\u0E19\u0E0B\u0E34\u0E0A\u0E31\u0E19",
    \u00DCbergangsmetalle: "\u0E42\u0E25\u0E2B\u0E30\u0E17\u0E23\u0E32\u0E19\u0E0B\u0E34\u0E0A\u0E31\u0E19",
    "Kategorie: Lanthanoide": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E41\u0E25\u0E19\u0E17\u0E32\u0E44\u0E19\u0E14\u0E4C",
    Lanthanoide: "\u0E41\u0E25\u0E19\u0E17\u0E32\u0E44\u0E19\u0E14\u0E4C",
    "Kategorie: Actinoide": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E41\u0E2D\u0E01\u0E17\u0E34\u0E44\u0E19\u0E14\u0E4C",
    Actinoide: "\u0E41\u0E2D\u0E01\u0E17\u0E34\u0E44\u0E19\u0E14\u0E4C",
    "Kategorie: Unbekannt": "\u0E2B\u0E21\u0E27\u0E14\u0E2B\u0E21\u0E39\u0E48: \u0E44\u0E21\u0E48\u0E17\u0E23\u0E32\u0E1A",
    Unbekannt: "\u0E44\u0E21\u0E48\u0E17\u0E23\u0E32\u0E1A",
