    "Kategorie: Erdalkalimetalle": "\u053F\u0561\u057F\u0565\u0563\u0578\u0580\u056B\u0561\u2024 \u0570\u0578\u0572\u0561\u056C\u056F\u0561\u056C\u056B\u0561\u056F\u0561\u0576 \u0574\u0565\u057F\u0561\u0572\u0576\u0565\u0580",
