    "Nur Inhalt": "\u0544\u056B\u0561\u0575\u0576 \u0562\u0578\u057E\u0561\u0576\u0564\u0561\u056F\u0578\u0582\u0569\u0575\u0578\u0582\u0576",
    "Panel-Ansicht": "\u054E\u0561\u0570\u0561\u0576\u0561\u056F\u0576\u0565\u0580\u056B \u0564\u0561\u057D\u0561\u057E\u0578\u0580\u0578\u0582\u0569\u0575\u0578\u0582\u0576",
    "Stoffmenge {symbol} Ionen [mol]": "{symbol} \u056B\u0578\u0576\u0576\u0565\u0580\u056B \u0576\u0575\u0578\u0582\u0569\u056B \u0584\u0561\u0576\u0561\u056F\u0568 [\u0574\u0578\u056C]",
