    Elemente: "\u05D9\u05E1\u05D5\u05D3\u05D5\u05EA",
    "Filter zur\xFCcksetzen": "\u05D0\u05D9\u05E4\u05D5\u05E1 \u05DE\u05E1\u05E0\u05E0\u05D9\u05DD",
    "Kategorie: Halogene": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05D4\u05DC\u05D5\u05D2\u05E0\u05D9\u05DD",
    Halogene: "\u05D4\u05DC\u05D5\u05D2\u05E0\u05D9\u05DD",
    "Kategorie: Nichtmetalle": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05D0\u05DC\u05BE\u05DE\u05EA\u05DB\u05D5\u05EA",
    Nichtmetalle: "\u05D0\u05DC\u05BE\u05DE\u05EA\u05DB\u05D5\u05EA",
    "Kategorie: Edelgase": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05D2\u05D6\u05D9\u05DD \u05D0\u05E6\u05D9\u05DC\u05D9\u05DD",
    Edelgase: "\u05D2\u05D6\u05D9\u05DD \u05D0\u05E6\u05D9\u05DC\u05D9\u05DD",
    "Kategorie: Alkalimetalle": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05DE\u05EA\u05DB\u05D5\u05EA \u05D0\u05DC\u05E7\u05DC\u05D9\u05D5\u05EA",
    Alkalimetalle: "\u05DE\u05EA\u05DB\u05D5\u05EA \u05D0\u05DC\u05E7\u05DC\u05D9\u05D5\u05EA",
    "Kategorie: Erdalkalimetalle": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05DE\u05EA\u05DB\u05D5\u05EA \u05D0\u05DC\u05E7\u05DC\u05D9\u05D5\u05EA \u05E2\u05E4\u05E8\u05D5\u05E8\u05D9\u05D5\u05EA",
    Erdalkalimetalle: "\u05DE\u05EA\u05DB\u05D5\u05EA \u05D0\u05DC\u05E7\u05DC\u05D9\u05D5\u05EA \u05E2\u05E4\u05E8\u05D5\u05E8\u05D9\u05D5\u05EA",
    "Kategorie: Halbmetalle": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05DE\u05EA\u05DB\u05D5\u05EA \u05DC\u05DE\u05D7\u05E6\u05D4",
    Halbmetalle: "\u05DE\u05EA\u05DB\u05D5\u05EA \u05DC\u05DE\u05D7\u05E6\u05D4",
    "Kategorie: \xDCbergangsmetalle": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05DE\u05EA\u05DB\u05D5\u05EA \u05DE\u05E2\u05D1\u05E8",
    \u00DCbergangsmetalle: "\u05DE\u05EA\u05DB\u05D5\u05EA \u05DE\u05E2\u05D1\u05E8",
    "Kategorie: Lanthanoide": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05DC\u05E0\u05EA\u05E0\u05D9\u05D3\u05D9\u05DD",
    Lanthanoide: "\u05DC\u05E0\u05EA\u05E0\u05D9\u05D3\u05D9\u05DD",
    "Kategorie: Actinoide": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05D0\u05E7\u05D8\u05D9\u05E0\u05D9\u05D3\u05D9\u05DD",
    Actinoide: "\u05D0\u05E7\u05D8\u05D9\u05E0\u05D9\u05D3\u05D9\u05DD",
    "Kategorie: Unbekannt": "\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4: \u05DC\u05D0 \u05D9\u05D3\u05D5\u05E2\u05D4",
    Unbekannt: "\u05DC\u05D0 \u05D9\u05D3\u05D5\u05E2",
    "Suche nach Name oder Symbol": "\u05D7\u05D9\u05E4\u05D5\u05E9 \u05DC\u05E4\u05D9 \u05E9\u05DD \u05D0\u05D5 \u05E1\u05DE\u05DC",
    Verbindungen: "\u05EA\u05E8\u05DB\u05D5\u05D1\u05D5\u05EA",
    "neu anlegen": "\u05D9\u05E6\u05D9\u05E8\u05D4 \u05D7\u05D3\u05E9\u05D4",
    Gegenst\u00FCck: "\u05D4\u05D7\u05DC\u05E7 \u05D4\u05EA\u05D5\u05D0\u05DD",
    Eigenschaften: "\u05DE\u05D0\u05E4\u05D9\u05D9\u05E0\u05D9\u05DD",
