    Erdalkalimetalle: "\u0787\u07AC\u078D\u07B0\u0786\u07A6\u078D\u07A6\u0787\u07A8\u0782\u07B0 \u0787\u07A7\u078C\u07AA \u0789\u07AC\u0793\u07A6\u078D\u07B0\u078C\u07A6\u0787\u07B0",
