    Lanthanoide: "\u078D\u07AC\u0782\u07B0\u078C\u07A6\u0782\u07A6\u0787\u07A8\u0791\u07B0\u078C\u07A6\u0787\u07B0",
    "Kategorie: Actinoide": "\u0784\u07A6\u0787\u07A8: \u0787\u07AC\u0786\u07B0\u0793\u07A8\u0782\u07A6\u0787\u07A8\u0791\u07B0\u078C\u07A6\u0787\u07B0",
    Actinoide: "\u0787\u07AC\u0786\u07B0\u0793\u07A8\u0782\u07A6\u0787\u07A8\u0791\u07B0\u078C\u07A6\u0787\u07B0",
