    "Inhalt aus {from} zu {to} \xFCberf\xFChrt.": "{from} \u0787\u07A8\u0782\u07B0 {to} \u0787\u07A6\u0781\u07B0 \u0786\u07AE\u0782\u07B0\u0793\u07AC\u0782\u07B0\u0793\u07B0 \u078E\u07AC\u0782\u07B0\u078B\u07A8\u0794\u07A6.",
    "Inhalt und Molek\xFCl": "\u0786\u07AE\u0782\u07B0\u0793\u07AC\u0782\u07B0\u0793\u07B0 \u0787\u07A6\u078B\u07A8 \u0789\u07AE\u078D\u07AC\u0786\u07A8\u0787\u07AA\u078D\u07B0",
    "Inhalt: Auswahl": "\u0786\u07AE\u0782\u07B0\u0793\u07AC\u0782\u07B0\u0793\u07B0 \u0780\u07AE\u0788\u07A7",
    "Inhalt: Volumen": "\u0786\u07AE\u0782\u07B0\u0793\u07AC\u0782\u07B0\u0793\u07B0\u078E\u07AC \u0788\u07AE\u078D\u07A8\u0787\u07AA\u0789\u07B0",
    "L\xF6sung in {name}": "{name} \u078E\u07A6\u0787\u07A8 \u0780\u07AA\u0783\u07A8 \u0790\u07AE\u078D\u07AB\u079D\u07A6\u0782\u07B0",
    Material: "\u0789\u07AC\u0793\u07A9\u0783\u07A8\u0787\u07A6\u078D\u07B0",
    Milliliter: "\u0789\u07A8\u078D\u07A8\u078D\u07A9\u0793\u07A6\u0783",
    "Molek\xFCl: Auswahl": "\u0789\u07AE\u078D\u07AC\u0786\u07A8\u0787\u07AA\u078D\u07AC\u0787\u07B0 \u0780\u07AE\u0788\u07A7",
    "Molek\xFCl: Stoffmenge": "\u0789\u07A7\u0787\u07B0\u078B\u07A7\u078E\u07AC \u0789\u07A8\u0782\u07B0",
    Name: "\u0782\u07A6\u0782\u07B0",
    "Neue Verbindung zwischen {from} und {to}": "{from} \u0787\u07A7\u0787\u07A8 {to} \u078E\u07AA\u0785\u07AA\u0788\u07A8",
